// src/infra/apps/utils/searchProviders.ts
function searchProviders(allProviders, limit, offset, searchTerm) {
  if (!searchTerm) {
    return allProviders.slice(offset, offset + limit);
  }
  const lowerSearchTerm = searchTerm.toLowerCase().trim();
  const allResults = allProviders.filter((provider) => {
    const firstName = provider.demographics.firstName.toLowerCase();
    const lastName = provider.demographics.lastName.toLowerCase();
    const fullName = `{${firstName} ${lastName}}`;
    return fullName.startsWith(lowerSearchTerm) || lastName.startsWith(lowerSearchTerm) || firstName.startsWith(lowerSearchTerm);
  });
  return allResults.slice(offset, offset + limit);
}

